          "id": "farmer-pm-kisan",
          "t": "పీఎం కిసాన్ సమ్మాన్ నిధి",
          "e": "PM-KISAN (Central)",
          "d": "కేంద్ర ప్రభుత్వం: అర్హులైన రైతు కుటుంబానికి ఏటా ₹6,000 - మూడు వాయిదాల్లో నేరుగా బ్యాంక్ ఖాతాలో. కొత్త నమోదు/స్టేటస్: పోర్టల్ లేదా మీ CSC కేంద్రం.",
