          "e": "Stree Nidhi (Women's loans)",
          "d": "మహిళా సంఘ (SHG) సభ్యులకు తక్కువ వడ్డీతో త్వరిత రుణాలు - జీవనోపాధి, వైద్యం, విద్య, అత్యవసర అవసరాలకు. మీ సంఘం / VO / మండల సమాఖ్య ద్వారా దరఖాస్తు.",
