          "t": "ముందు తెలుసుకోండి - రుణం/సబ్సిడీ ఎవరికీ హామీ కాదు",
          "e": "Read first - no loan or subsidy is guaranteed",
          "d": "ప్రతి రుణం బ్యాంకు/సంస్థ మంజూరు మీదే ఆధారపడుతుంది - ఎవరూ మంజూరును హామీ ఇవ్వలేరు. సబ్సిడీ లేదా ప్రోత్సాహకం ఆయా పథకం నిబంధనలు, అర్హత పరిశీలన, అధికారిక మంజూరుపై ఆధారపడుతుంది; ముందుగా డబ్బు వస్తుందని అనుకోకండి. ఉద్యమ్ రిజిస్ట్రేషన్ అధికారిక పోర్టల్‌లో (udyamregistration.gov.in) 100% ఉచితం - ఫీజు వసూలు చేసే నకిలీ సైట్ల నుండి జాగ్రత్త. బ్యాంకు/పోర్టళ్ల నిజమైన ఫీజులు ఉండవచ్చు - చెల్లింపు ముందు అధికారిక సైట్/బ్యాంకులోనే మొత్తం నిర్ధారించుకోండి. గ్యారంటీ ఇస్తాననే అనధికారిక ఏజెంట్లకు డబ్బు ఇవ్వవద్దు; OTP, ఆధార్ నంబరు ఎవరితోనూ షేర్ చేయవద్దు.",
