          "e": "Udyam Registration (MSME)",
          "d": "నిబంధనల్లో కప్పబడిన తయారీ/సేవా కార్యకలాపాల చిన్న వ్యాపారం, యూనిట్ MSME గా నమోదు చేసుకునే అధికారిక కేంద్ర పోర్టల్ (మినహాయించిన కార్యకలాపాలకు వర్తించదు). ఆధార్ + PAN తో ఉచితం, కాగితాలు అవసరం లేదు; GST నమోదు తప్పనిసరి ఉన్న యూనిట్లు GSTIN కూడా ఇవ్వాలి (నోటిఫికేషన్ నిబంధనల ప్రకారం). ఈ సర్టిఫికేట్ ఆధారంగా బ్యాంకు లోన్లు, ప్రభుత్వ పథకాలు, టెండర్లకు దరఖాస్తు సులభం - అయితే ప్రయోజనాలు ఆయా పథకం, బ్యాంకు అర్హత నిబంధనల మేరకే నిర్ణయించబడతాయి; నమోదు ఉంటే చాలు, ఆటోమేటిక్ గా లభించవు. వర్గీకరణ పెట్టుబడి + టర్నోవర్ రెండింటి ఆధారంగానే: మైక్రో యూనిట్ అంటే పెట్టుబడి 2.5 కోట్లు మరియు టర్నోవర్ 10 కోట్లు మించనిది.",
