          "d": "MSMED చట్టం సెక్షన్ 15 ప్రకారం: రాతపూర్వక ఒప్పందం ఉంటే కొనుగోలుదారు అంగీకరించిన తేదీలోపు, గరిష్ఠంగా 45 రోజుల్లో చెల్లించాలి; రాతపూర్వక ఒప్పందం లేకపోతే సరుకులు/సేవలు అందుకున్న రోజు నుండి 15 రోజుల్లోపు చెల్లించాల్సిందే. చెల్లించకపోతే మైక్రో, స్మాల్ యూనిట్లు మాత్రమే samadhaan.msme.gov.in లో MSE Facilitation Council కు ఆన్‌లైన్ ఫిర్యాదు చేసి స్థితి చూడవచ్చు - మీడియం యూనిట్లకు ఈ సదుపాయం లేదు.",
