          "d": "కొత్త చిన్న తయారీ/సేవా యూనిట్ పెట్టేవారికి బ్యాంకు లోన్ + ప్రభుత్వ మార్జిన్ మనీ సబ్సిడీ (కేటగిరీ, ప్రాంతం మేరకు మారుతుంది - ప్రస్తుత శాతం అధికారిక పోర్టల్‌లో చూడండి). ఆన్‌లైన్ దరఖాస్తు, ఆధార్ ధృవీకరణ, దరఖాస్తు నుండి సబ్సిడీ విడుదల వరకు స్థితి ట్రాక్ చేయవచ్చు. ఇప్పటికే ప్రభుత్వ సబ్సిడీ తీసుకున్న యూనిట్లు కొత్త యూనిట్ ఏర్పాటు భాగానికి అర్హులు కావు; అయితే ఉన్న PMEGP యూనిట్ల ఆధునీకరణ, విస్తరణ కోసం రెండో రుణ (అప్‌గ్రేడేషన్) మార్గం ప్రత్యేకంగా ఉంది - వివరాలు పోర్టల్‌లో చూడండి. సబ్సిడీ అంటే బ్యాంకు లోన్ మంజూరై, ధృవీకరణ జరిగిన తర్వాతే - ముందుగా డబ్బు రాదు.",
