          "t": "PM విశ్వకర్మ - చేతివృత్తులవారికి",
          "e": "PM Vishwakarma - for artisans",
          "d": "ప్రభుత్వం నోటిఫై చేసిన 18 చేతివృత్తుల్లో (దర్జీ, ముచ్చి/చార్మకారుడు, కుమ్మరి, కమ్మరి-లోహార్, వడ్రంగి, మంగలి, ధోబి, రాజ్ మిస్త్రీ తదితర) మీ వృత్తి ఉన్నవారికే అర్హత - అన్ని కళాకారులకూ కాదు. టూల్ కిట్ కోసం 15,000 రూ. ఇ-వోచర్, శిక్షణ కాలంలో రోజుకు 500 రూ. స్టైపెండ్, తనఖా లేని రుణం మొదట 1 లక్ష, తర్వాత 2 లక్షల వరకు 5% రాయితీ వడ్డీతో. నమోదు ఉచితం - CSC/గ్రామ పంచాయతీ వద్ద.",
          "de": "For 18 traditional trades (tailor, carpenter, potter, blacksmith, barber, washerman, artisan and more): Rs 15,000 e-voucher for a toolkit, Rs 500/day stipend during training, collateral-free loan of Rs 1 lakh first and up to Rs 2 lakh later at 5% concessional interest. Registration is free at CSC/Gram Panchayat.",
          "bt": "నమోదు సమాచారం",
