          "id": "biz-svanidhi",
          "t": "PM స్వనిధి - వీధి వ్యాపారులకు",
          "e": "PM SVANidhi - street vendors",
          "d": "బండ్లు, కూరగాయల/పండ్ల అమ్మకాలు, టీ బండ్ల వంటి వీధి వ్యాపారులకు తనఖా లేని చిన్న రుణాలు: ముందు 15 వేలు, సక్రమంగా తీర్చితే 25 వేలు, ఆ తర్వాత 50 వేల వరకు (27-08-2025 కేబినెట్ నిర్ణయంతో పెరిగిన మొత్తాలు). పథకం 31-03-2030 వరకు పొడిగింపు; రెండో రుణం తీర్చినవారికి UPI-లింక్డ్ RuPay క్రెడిట్ కార్డు. పట్టణాలతో పాటు సెన్సస్ టౌన్‌లు, పరి-పట్టణ ప్రాంతాలకు విస్తరిస్తున్నారు - మన ప్రాంతం పరిధిలోకి వస్తుందో మండల కార్యాలయంలో నిర్ధారించుకోండి.",
          "de": "Collateral-free small loans for street vendors (carts, vegetable/fruit sellers, tea stalls): Rs 15,000 first, Rs 25,000 after timely repayment, then up to Rs 50,000 (amounts raised by the 27-08-2025 Cabinet decision). Scheme extended to 31-03-2030; a UPI-linked RuPay credit card after repaying the second loan. Coverage is expanding beyond towns to census towns and peri-urban areas - confirm with the mandal office whether our area is covered.",
