          "e": "TG-iPASS - industrial approvals",
          "d": "కొత్త పరిశ్రమ/యూనిట్ పెట్టేవారికి చట్టం కవర్ చేసే అనేక శాఖల అనుమతులు ఒకే ఆన్‌లైన్ విండో - సెల్ఫ్ సర్టిఫికేషన్; పూర్తిగా సరైన దరఖాస్తుపై చట్టపరమైన గడువులు వర్తిస్తాయి, 'అన్ని అనుమతులు 30 రోజుల్లోనే' అని సాధారణ హామీ కాదు. T-PRIDE కింద SC/ST పారిశ్రామికవేత్తలకు 35% వరకు పెట్టుబడి సబ్సిడీ వంటి ప్రోత్సాహకాలు జిల్లా పరిశ్రమల కేంద్రం (DIC) ద్వారా - ప్రస్తుత లభ్యత DIC మెదక్‌లో నిర్ధారించుకోండి.",
