          "e": "DIKSHA - Free Lessons (Children & Teachers)",
          "d": "ప్రభుత్వ అధికారిక ఉచిత లెర్నింగ్ యాప్/వెబ్‌సైట్ - స్కూల్ పాఠ్యాంశాలు, వీడియో పాఠాలు, క్విజ్‌లు తెలుగుతో సహా. ఇంటర్నెట్ ఉంటే ఎవరైనా ఉచితంగా నేర్చుకోవచ్చు.",
